FileOpen:
	lda xsp, (xsp - 16)
	push xiz
	ld xbc, (xsp + 28)
	ld xwa, (xsp + 24)
	or xwa, xwa
	jrl z, FileOpen_ErrorNoFile
	lda_24 xwa, 0xf4f05a
	st32_24 0x0210f6, xwa
	ld (xsp + 4), 0x4
	cp (xbc), 0x0
	jr z, FileOpen_AllocBuffer

FileOpen_ParseModeLoop:
	ld_spib A, 0xE4
	exts wa
	cp wa, 0x64
	jr z, FileOpen_ModeD
	cp wa, 0x7E
	jr z, FileOpen_ModeTilde
	cp wa, 0x62
	jr z, FileOpen_ModeB
	cp wa, 0x2B
	jr z, FileOpen_ModePlus
	cp wa, 0x61
	jr z, FileOpen_ModeA
	cp wa, 0x77
	jr z, FileOpen_ModeW
	cp wa, 0x72
	jr nz, FileOpen_ParseModeNext
	setm 0, (xsp + 4)
	jr FileOpen_ParseModeNext

FileOpen_ModeW:
	ormi8 (xsp + 4), 0x92
	jr FileOpen_ParseModeNext

FileOpen_ModeA:
	ormi8 (xsp + 4), 0x8A
	jr FileOpen_ParseModeNext

FileOpen_ModePlus:
	ormi8 (xsp + 4), 0x3
	jr FileOpen_ParseModeNext

FileOpen_ModeB:
	resm 2, (xsp + 4)
	jr FileOpen_ParseModeNext

FileOpen_ModeTilde:
	setm 5, (xsp + 4)
	jr FileOpen_ParseModeNext

FileOpen_ModeD:
	ormi8 (xsp + 4), 0x41
	resm 2, (xsp + 4)

FileOpen_ParseModeNext:
	cp (xbc), 0x0
	jr nz, FileOpen_ParseModeLoop

FileOpen_AllocBuffer:
	ld xwa, (xsp + 24)
	push xwa
	call Strlen
	inc 1, hl
	pushw hl
	calr SeqStep_MemAllocWrapper
	inc 6, xsp
	ld (xsp + 12), xhl
	or xhl, xhl
	jr nz, FileOpen_CopyFilename
	lds32 xhl, 0
	jrl FileOpen_Return

FileOpen_CopyFilename:
	ld xwa, (xsp + 24)
	push xwa
	ld xwa, (xsp + 16)
	push xwa
	call Strcpy
	inc 8, xsp
	ld xwa, (xsp + 12)
	ld (xsp + 16), xwa

FileOpen_NormalizeName:
	ld xde, (xsp + 16)
	ld xwa, xde
	ld a, (xwa)
	extz wa
	lda_24 xbc, 0xeed778
	ld_srib3 A, 0x07, 0xE4, 0xE0
	bit 1, a
	jr z, FileOpen_NormalizeNoUpper
	ld xwa, (xsp + 16)
	ld a, (xwa)
	exts wa
	sub wa, 0x20
	jr FileOpen_StoreNormChar

FileOpen_ScanForColon:
	ld xwa, (xsp + 16)
	ld_spib C, 0xE0
	ld (xsp + 16), xwa
	cp c, 0x3A
	jr nz, FileOpen_NormalizeName
	lds32 xwa, 1
	sub (xsp + 16), xwa
	ld xwa, (xsp + 16)
	stib_dpi 0xE0, 0x00
	ld (xsp + 16), xwa
	jr FileOpen_MatchDevice

FileOpen_NormalizeNoUpper:
	ld xwa, (xsp + 16)
	ld a, (xwa)
	exts wa

FileOpen_StoreNormChar:
	ld (xde), a
	cps a, 0
	jr nz, FileOpen_ScanForColon

FileOpen_MatchDevice:
	ld xwa, (xsp + 16)
	push xwa
	call Strlen
	ld iz, hl
	extz xiz
	ld xwa, (xsp + 28)
	push xwa
	call Strlen
	inc 8, xsp
	ld wa, hl
	extz xwa
	ld xbc, (xsp + 24)
	ld (xsp + 16), xbc
	add (xsp + 16), xwa
	sub (xsp + 16), xiz
	ld (xsp + 6), 0x0
	lda_24 xwa, 0x03e3bc
	ld (xsp + 8), xwa
	ld a, (xsp + 6)
	extz wa
	cpda16_24 xwa, 254942
	jr ge, FileOpen_DeviceFound

FileOpen_DeviceSearchLoop:
	ld xwa, (xsp + 8)
	ld xwa, (xwa + 22)
	push xwa
	ld xwa, (xsp + 16)
	push xwa
	call Strcmp
	inc 8, xsp
	cps hl, 0
	jr z, FileOpen_DeviceFound
	incm8 1, (xsp + 6)
	ld xwa, 0x22
	add (xsp + 8), xwa
	ld a, (xsp + 6)
	extz wa
	cpda16_24 xwa, 254942
	jr lt, FileOpen_DeviceSearchLoop

FileOpen_DeviceFound:
	ld xwa, (xsp + 12)
	push xwa
	call SeqStep_FreeMemory
	inc 4, xsp
	ld a, (xsp + 6)
	extz wa
	cpda16_24 xwa, 254942
	jr nz, FileOpen_CheckPermission

FileOpen_ErrorNoFile:
	sti16_24 0x01e53c, 0x0007
	lds32 xhl, 0
	jrl FileOpen_Return

FileOpen_CheckPermission:
	ld a, (xsp + 4)
	and a, 0xF
	ld c, a
	ld xwa, (xsp + 8)
	ld a, (xwa + 1)
	extz wa
	cpl wa
	and a, c
	jr z, FileOpen_FindFreeSlot
	sti16_24 0x01e53c, 0x0002
	lds32 xhl, 0
	jrl FileOpen_Return

FileOpen_FindFreeSlot:
	incdi8_24 1, 135412
	ld (xsp + 14), 0x0
	cp (xsp + 14), 0x10
	jr nc, FileOpen_SlotExhausted

FileOpen_SlotSearchLoop:
	ld a, (xsp + 14)
	extz wa
	sla wa, 2
	lda_24 xbc, 0x0210b4
	ld_sril3 XWA, 0x07, 0xE4, 0xE0
	or xwa, xwa
	jr z, FileOpen_SlotExhausted
	incm8 1, (xsp + 14)
	cp (xsp + 14), 0x10
	jr c, FileOpen_SlotSearchLoop

FileOpen_SlotExhausted:
	cp (xsp + 14), 0x10
	jr nz, FileOpen_InitSlot
	sti16_24 0x01e53c, 0x0004
	call SeqStep_FileNopB
	lds32 xhl, 0
	jrl FileOpen_Return

FileOpen_InitSlot:
	ld a, (xsp + 14)
	extz wa
	ld bc, wa
	sla bc, 2
	lda_24 xde, 0x0210b4
	ld xwa, 0xFFFFFFFF
	st_dri3l XWA, 0x07, 0xE8, 0xE4
	call SeqStep_FileNopB
	pushw 0x4B
	calr SeqStep_MemAllocWrapper
	inc 2, xsp
	ld xwa, (xsp + 8)
	ld (xwa + 30), xhl
	ld xiz, xhl
	or xiz, xiz
	jr nz, FileOpen_PopulateStruct
	ld a, (xsp + 14)
	extz wa
	ld bc, wa
	sla bc, 2
	lda_24 xde, 0x0210b4
	lds32 xwa, 0
	st_dri3l XWA, 0x07, 0xE8, 0xE4
	lds32 xhl, 0
	jrl FileOpen_Return

FileOpen_PopulateStruct:
