	lds32 xwa, 0
	st_dri3l XWA, 0x07, 0xE8, 0xE4
	ld a, l
	exts wa
	st16_24 0x01e53c, xwa
	ld xwa, xiz
	push xwa
	call SeqStep_FreeMemory
	inc 4, xsp
	lds32 xiz, 0

FileOpen_ReturnHandle:
