SeqStep_FileSectorRead:
	ld xbc, (xsp + 4)
	ld xde, (xbc)
	lds32 xwa, 1
	add (xbc), xwa
	ld l, (xde)
	extz hl
	ld xbc, (xsp + 4)
	ld xde, (xbc)
	lds32 xwa, 1
	add (xbc), xwa
	ld a, (xde)
	extz wa
	sll wa, 8
	add hl, wa
	ret

SeqStep_FileSectorProcess:
	ld xix, (xsp + 4)
	ld xbc, xix
	ld xde, (xbc)
	lds32 xwa, 1
	add (xbc), xwa
	ld a, (xde)
	lds32 xhl, 0
	ld l, a
	ld xbc, xix
	ld xde, (xbc)
	lds32 xwa, 1
	add (xbc), xwa
	lds32 xwa, 0
	ld a, (xde)
	sll xwa, 8
	add xhl, xwa
	ld xbc, xix
	ld xde, (xbc)
	lds32 xwa, 1
	add (xbc), xwa
	lds32 xwa, 0
	ld a, (xde)
	sll xwa, 0
	add xhl, xwa
	ld xbc, xix
	ld xde, (xbc)
	lds32 xwa, 1
	add (xbc), xwa
	lds32 xwa, 0
	ld a, (xde)
	sll xwa, 8
	sll xwa, 0
	add xhl, xwa
	ret

SeqStep_FileSectorDone:
	.byte 0xaf, 0x06, 0x21, 0xa1, 0x22, 0xe8, 0xa9, 0xa1
	.byte 0x88, 0x9f, 0x04, 0x20, 0x20, 0x00, 0xb2, 0x41
	.byte 0xaf, 0x06, 0x21, 0xa1, 0x22, 0xe8, 0xa9, 0xa1
