	.byte 0x8a, 0xa2, 0x24, 0xe8, 0xa9, 0xa2, 0x88, 0xeb
	.long LABEL_EFE888
	.long AudioCmd_FillToVectors
	nop
	nop
	ld	(xix), a
	ld	xde, (xbc)
	lds32	xwa, 1
	add	(xbc), xwa
	ld	xwa, xhl
	srl	xwa, 8
	srl	xwa, 0
	and	xwa, 255
	ld	(xde), a
	ret

SeqStep_FileSectorComplete:
	dec 4, xsp
	push xiz
	ld xiz, (xsp + 16)
	lda xwa, (xiz + 22)
	ld (xsp + 4), xwa
	pushw 0xB
	ld xwa, xiz
	push xwa
	ld xwa, (xsp + 18)
	push xwa
	call Mem_Copy
	ld xwa, (xsp + 22)
	ld (xwa + 11), 0x0
	ld xwa, (xsp + 22)
	ld c, (xiz + 11)
	ld (xwa + 12), c
	lda xwa, (xsp + 14)
	push xwa
	calr SeqStep_FileSectorRead
	ld xwa, (xsp + 26)
	ld (xwa + 13), hl
	lda xwa, (xsp + 18)
	push xwa
	calr SeqStep_FileSectorRead
	ld xwa, (xsp + 30)
	ld (xwa + 15), hl
	lda xwa, (xsp + 22)
	push xwa
	calr SeqStep_FileSectorRead
	ld xwa, (xsp + 34)
	ld (xwa + 17), hl
	lda xwa, (xsp + 26)
	push xwa
	calr SeqStep_FileSectorProcess
	lda xsp, (xsp + 26)
	ld xwa, (xsp + 12)
	ld (xwa + 19), xhl
	pop xiz
	inc 4, xsp
	ret

